select r->>'horse_no' as horse_no,r->'score' as frozen_score,r->'rank' as frozen_rank,p.payload->'audit'->'manual_score_breakdown'->'maxima' as maxima,p.payload->'audit'->'evidence_rank_bridge'->'version' as bridge_version from public.official_predictions p cross join lateral jsonb_array_elements(p.payload->'runners') r where p.race_date='2026-11-14' and p.track='京都' and p.race_no=8 and p.status='FROZEN' order by (r->>'horse_no')::int;
